export const EdgeEnvelopeTagMixed = 1n;
export const EdgeEnvelopeTagVarint = 300n;
export const EdgeEnvelopeTagQuantized = 9007199254740993n;

// EdgeEnvelope exercises a uvarint-discriminated union.
export interface EdgeEnvelope {
  tag: bigint;
  mixed: MixedEndian;
  varint: VarintEdge;
  quantized: QuantizedPacket;
}

export function createEdgeEnvelope(): EdgeEnvelope {
  return {
    tag: 0n,
    mixed: createMixedEndian(),
    varint: createVarintEdge(),
    quantized: createQuantizedPacket(),
  };
}

export function encodeEdgeEnvelope(m: EdgeEnvelope, w: Writer): void {
  w.writeUvarintBig(m.tag);
  switch (m.tag) {
    case EdgeEnvelopeTagMixed:
      encodeMixedEndian(m.mixed, w);
      break;
    case EdgeEnvelopeTagVarint:
      encodeVarintEdge(m.varint, w);
      break;
    case EdgeEnvelopeTagQuantized:
      encodeQuantizedPacket(m.quantized, w);
      break;
  }
}

export function decodeEdgeEnvelope(r: Reader, m: EdgeEnvelope): void {
  const tag = r.readUvarintBig();
  m.tag = tag;
  switch (tag) {
    case EdgeEnvelopeTagMixed:
      decodeMixedEndian(r, m.mixed);
      break;
    case EdgeEnvelopeTagVarint:
      decodeVarintEdge(r, m.varint);
      break;
    case EdgeEnvelopeTagQuantized:
      decodeQuantizedPacket(r, m.quantized);
      break;
    default:
      throw new WireError("invalid_tag", "wire: unknown message tag");
  }
}

